import pytest
from mdinline import render


class TestInputValidation:
    """Test input validation."""

    def test_newline_raises_error(self):
        with pytest.raises(ValueError):
            render("one\ntwo")

    def test_carriage_return_raises_error(self):
        with pytest.raises(ValueError):
            render("one\rtwo")

    def test_newline_and_carriage_return_raises_error(self):
        with pytest.raises(ValueError):
            render("one\r\ntwo")


class TestHTMLEscaping:
    """Test HTML escaping of special characters."""

    def test_ampersand_escaped(self):
        assert render("a & b") == "a &amp; b"

    def test_less_than_escaped(self):
        assert render("a < b") == "a &lt; b"

    def test_greater_than_escaped(self):
        assert render("a > b") == "a &gt; b"

    def test_quote_escaped(self):
        assert render('a " b') == "a &quot; b"

    def test_multiple_special_chars_escaped(self):
        assert render("a & b < c > d & e") == "a &amp; b &lt; c &gt; d &amp; e"

    def test_escaping_in_code_span(self):
        assert render("use `a&b<c>d`") == "use <code>a&amp;b&lt;c&gt;d</code>"

    def test_escaping_with_emphasis(self):
        assert render("*a & b*") == "<em>a &amp; b</em>"


class TestBackslashEscapes:
    """Test backslash escape functionality."""

    def test_backslash_before_asterisk(self):
        assert render(r"\*not emphasis\*") == "*not emphasis*"

    def test_backslash_before_underscore(self):
        assert render(r"\_ underscore") == "_ underscore"

    def test_backslash_before_backtick(self):
        assert render(r"\` backtick") == "` backtick"

    def test_backslash_before_other_punctuation(self):
        assert render(r"\!") == "!"
        assert render(r"\#") == "#"
        assert render(r"\[") == "["
        assert render(r"\]") == "]"

    def test_backslash_before_non_punctuation_is_literal(self):
        assert render(r"\a") == r"\a"
        assert render(r"\1") == r"\1"

    def test_backslash_at_end_of_line_is_literal(self):
        assert render("test\\") == "test\\"

    def test_backslash_before_space_is_literal(self):
        assert render(r"\ space") == r"\ space"

    def test_multiple_backslashes(self):
        assert render(r"\\") == r"\\"
        assert render(r"\\\*") == r"\*"


class TestCodeSpans:
    """Test code span functionality."""

    def test_single_backtick_code_span(self):
        assert render("use `code` here") == "use <code>code</code> here"

    def test_code_span_with_asterisks_not_emphasized(self):
        assert render("use `a*b` here") == "use <code>a*b</code> here"

    def test_code_span_with_underscores(self):
        assert render("use `a_b` here") == "use <code>a_b</code> here"

    def test_double_backtick_code_span(self):
        assert render("`` a ` b ``") == "<code>a ` b</code>"

    def test_triple_backtick_code_span(self):
        assert render("``` a `` b ```") == "<code>a `` b</code>"

    def test_unmatched_backtick_is_plain_text(self):
        assert render("use `code here") == "use `code here"

    def test_different_backtick_length_no_match(self):
        assert render("`single `` and double`") == "`single `` and double`"

    def test_code_span_with_space_trimming_start_and_end(self):
        assert render("` code `") == "<code>code</code>"

    def test_code_span_with_space_trimming_only_one_removed(self):
        assert render("`  code  `") == "<code> code </code>"

    def test_code_span_all_spaces_no_trimming(self):
        assert render("`   `") == "<code>   </code>"

    def test_code_span_with_space_only_at_start(self):
        assert render("` code`") == "<code> code</code>"

    def test_code_span_with_space_only_at_end(self):
        assert render("`code `") == "<code>code </code>"

    def test_code_span_binds_tighter_than_emphasis(self):
        assert render("*a `*` b*") == "<em>a <code>*</code> b</em>"

    def test_escaped_backtick_not_a_backtick_string(self):
        assert render(r"\` test") == "` test"

    def test_code_span_with_html_chars(self):
        assert render("`a & b < c`") == "<code>a &amp; b &lt; c</code>"

    def test_multiple_code_spans(self):
        assert render("`a` and `b`") == "<code>a</code> and <code>b</code>"

    def test_nested_backtick_longer_closer(self):
        assert render("`` ` ``") == "<code>`</code>"


class TestEmphasis:
    """Test emphasis (single and strong) functionality."""

    def test_basic_emphasis(self):
        assert render("*hello*") == "<em>hello</em>"

    def test_basic_strong_emphasis(self):
        assert render("**hello**") == "<strong>hello</strong>"

    def test_multiple_emphasis(self):
        assert render("*Hello* **world**") == "<em>Hello</em> <strong>world</strong>"

    def test_emphasis_with_underscore(self):
        assert render("_hello_") == "<em>hello</em>"

    def test_strong_emphasis_with_underscore(self):
        assert render("__hello__") == "<strong>hello</strong>"

    def test_nested_emphasis_bold_and_italic(self):
        assert render("**bold *and* italic**") == "<strong>bold <em>and</em> italic</strong>"

    def test_nested_italic_and_bold(self):
        assert render("*italic **and** bold*") == "<em>italic <strong>and</strong> bold</em>"

    def test_triple_asterisk_emphasis_then_strong(self):
        assert render("***a***") == "<em><strong>a</strong></em>"

    def test_strong_then_emphasis_leftover(self):
        assert render("**a*") == "*<em>a</em>"

    def test_emphasis_then_strong_leftover(self):
        assert render("*a**") == "<em>a</em>*"

    def test_underscore_does_not_emphasize_inside_word(self):
        assert render("snake_case_name") == "snake_case_name"

    def test_underscore_at_word_boundary_emphasizes(self):
        assert render("_hello_ world") == "<em>hello</em> world"

    def test_emphasis_not_matched_across_different_chars(self):
        assert render("*hello_") == "*hello_"

    def test_multiple_separate_emphasis(self):
        assert render("*a* *b*") == "<em>a</em> <em>b</em>"

    def test_emphasis_with_text_before_and_after(self):
        assert render("before *emphasis* after") == "before <em>emphasis</em> after"

    def test_matching_rule_sum_multiple_of_3(self):
        # Rule: When either can both open and close, they cannot match if sum is multiple of 3
        # unless both are multiples of 3
        assert render("*foo**bar*") == "<em>foo**bar</em>"

    def test_multiple_of_3_rule_both_multiples(self):
        assert render("***foo***bar***") == "<em><strong>foo</strong></em>bar<em><strong></strong></em>"

    def test_emphasis_requires_left_flanking_to_open(self):
        # After opening delimiter, next char must not be whitespace
        assert render("* not emphasis *") == "* not emphasis *"

    def test_emphasis_requires_right_flanking_to_close(self):
        # Before closing delimiter, previous char must not be whitespace
        assert render("*not emphasis *") == "*not emphasis *"

    def test_left_flanking_with_punctuation_after(self):
        # For *, left-flanking if after is not whitespace AND (after is not punctuation OR before is whitespace/punctuation)
        assert render("(*a*)") == "(<em>a</em>)"

    def test_underscore_no_open_right_flanking_not_left_flanking(self):
        # _ can open only if left-flanking and not right-flanking or before is punctuation
        assert render("_a_") == "<em>a</em>"

    def test_underscore_in_middle_of_word_right_flanking_no_left(self):
        assert render("a_b") == "a_b"

    def test_mixed_emphasis_markers(self):
        assert render("*a _b_ c*") == "<em>a <em>b</em> c</em>"


class TestComplexCases:
    """Test complex combinations of features."""

    def test_code_span_inside_emphasis(self):
        assert render("*use `code` here*") == "<em>use <code>code</code> here</em>"

    def test_emphasis_inside_code_span_not_applied(self):
        assert render("`*not emphasized*`") == "<code>*not emphasized*</code>"

    def test_backslash_escape_inside_code_span_is_literal(self):
        assert render(r"`\*`") == r"<code>\*</code>"

    def test_multiple_emphasis_different_chars(self):
        assert render("*a* _b_") == "<em>a</em> <em>b</em>"

    def test_emphasis_across_code_span_boundary(self):
        # Code spans bind tighter, so this shouldn't match
        assert render("*a `b*` c") == "*a <code>b*</code> c"

    def test_leading_whitespace_preserved(self):
        assert render("  text") == "  text"

    def test_trailing_whitespace_preserved(self):
        assert render("text  ") == "text  "

    def test_leading_and_trailing_whitespace_preserved(self):
        assert render("  text  ") == "  text  "

    def test_empty_string(self):
        assert render("") == ""

    def test_whitespace_only(self):
        assert render("   ") == "   "

    def test_emphasis_with_leading_trailing_spaces(self):
        assert render(" *text* ") == " <em>text</em> "

    def test_complex_nested_emphasis(self):
        assert render("*a **b *c* d** e*") == "<em>a <strong>b <em>c</em> d</strong> e</em>"

    def test_all_features_combined(self):
        assert render(r"*use `\*code\*` for *emphasis***") == "<em>use <code>*code*</code> for <em>emphasis</em></em>"


class TestEdgeCases:
    """Test edge cases and boundary conditions."""

    def test_single_asterisk(self):
        assert render("*") == "*"

    def test_single_underscore(self):
        assert render("_") == "_"

    def test_single_backtick(self):
        assert render("`") == "`"

    def test_non_ascii_punctuation_no_escape(self):
        # Non-ASCII punctuation character should not be escapable
        assert render("\\—") == "\\—"

    def test_unicode_in_text(self):
        assert render("café") == "café"

    def test_unicode_emphasis(self):
        assert render("*café*") == "<em>café</em>"

    def test_unicode_in_code_span(self):
        assert render("`café`") == "<code>café</code>"

    def test_multiple_consecutive_emphasis_markers(self):
        assert render("****a****") == "<strong><strong>a</strong></strong>"

    def test_asterisk_at_line_start_counts_as_start_whitespace(self):
        # Start of line counts as whitespace, so *a is left-flanking
        assert render("*a*") == "<em>a</em>"

    def test_asterisk_at_line_end_counts_as_end_whitespace(self):
        # End of line counts as whitespace, so a* is right-flanking
        assert render("*a*") == "<em>a</em>"

    def test_empty_code_span(self):
        assert render("``") == "``"

    def test_empty_emphasis(self):
        assert render("**") == "**"

    def test_code_span_with_backtick_inside_different_length(self):
        assert render("`` ` ``") == "<code>`</code>"

    def test_very_long_delimiter_run(self):
        # Test that long runs work correctly
        assert render("*" * 10 + "a" + "*" * 10) == "<em><strong>a</strong></em>" + "*" * 6

    def test_mixed_emphasis_and_escapes(self):
        assert render(r"*a\*b*") == r"<em>a*b</em>"

    def test_backtick_in_escaped_form(self):
        assert render(r"\`test\`") == "`test`"

    def test_space_trimming_with_code_span_next_to_emphasis(self):
        assert render("*` a `*") == "<em><code>a</code></em>"

    def test_html_chars_in_different_contexts(self):
        result = render("*a&b* `c<d` e>f")
        assert "&amp;" in result
        assert "&lt;" in result
        assert "&gt;" in result

    def test_emphasis_with_internal_punctuation(self):
        assert render("*hello-world*") == "<em>hello-world</em>"

    def test_tabs_and_special_whitespace(self):
        assert render("\ta\tb") == "\ta\tb"
        assert render("*\ta\t*") == "<em>\ta\t</em>"

