class TestCodeSpans:
    """Test code span rendering."""

    def test_single_backtick_code_span(self):
        assert render("`code`") == "<code>code</code>"

    def test_code_span_with_asterisks(self):
        assert render("use `a*b` here") == "use <code>a*b</code> here"

    def test_code_span_with_emphasis_chars(self):
        assert render("`*_*_`") == "<code>*_*_</code>"

