        assert render("``a ` b``") == "<code>a ` b</code>"

    def test_triple_backtick_code_span(self):
        assert render("```a `` b```") == "<code>a `` b</code>"

    def test_unmatched_backtick_is_literal(self):
        assert render("`unclosed") == "`unclosed"

    def test_backtick_different_lengths_no_match(self):
        # Single backtick doesn't match double backtick
        assert render("`a``b`") == "`a``b`"

    def test_code_span_with_leading_space_stripped(self):
        assert render("` a `") == "<code>a</code>"

    def test_code_span_with_trailing_space_stripped(self):
        assert render("`a `") == "<code>a</code>"

    def test_code_span_with_leading_and_trailing_space_stripped(self):
        assert render("` a `") == "<code>a</code>"

    def test_code_span_with_only_spaces_not_stripped(self):
        assert render("`   `") == "<code>   </code>"

    def test_code_span_space_stripped_only_if_both_ends(self):
