    def test_simple_strong(self):
        assert render("**hello**") == "<strong>hello</strong>"

    def test_emphasis_and_strong_together(self):
        assert render("*Hello* **world**") == "<em>Hello</em> <strong>world</strong>"

    def test_nested_strong_in_emphasis(self):
        assert render("*bold **and** italic*") == "<em>bold <strong>and</strong> italic</em>"

    def test_nested_emphasis_in_strong(self):
        assert render("**bold *and* italic**") == "<strong>bold <em>and</em> italic</strong>"

    def test_emphasis_with_underscore(self):
        assert render("_hello_") == "<em>hello</em>"

    def test_strong_with_underscore(self):
        assert render("__hello__") == "<strong>hello</strong>"

    def test_triple_asterisk_mixed(self):
        assert render("***a***") == "<em><strong>a</strong></em>"

    def test_triple_asterisk_different_order(self):
        # Three asterisks, consumed as 2+1 from left, closes with 2+1 from right
        assert render("***a***") == "<em><strong>a</strong></em>"

    def test_four_asterisk_strong_twice(self):
        assert render("****a****") == "<strong><strong>a</strong></strong>"

    def test_emphasis_not_matching_length_multiple_of_3(self):
        # Length 1+1=2 (not multiple of 3), can match
        assert render("*a*b*c*") == "<em>a</em>b<em>c</em>"

