        # _before punctuation can open if left-flanking
        assert render("_foo.") == "_foo."

    def test_underscore_after_punctuation_can_close(self):
        # _after punctuation can close if right-flanking
        assert render(".foo_") == ".foo_"

    def test_asterisk_emphasizes_inside_word(self):
        # Asterisk follows different rules than underscore
        assert render("*hello*") == "<em>hello</em>"

    def test_left_flanking_requires_no_whitespace_after(self):
        # Left-flanking: after is not whitespace
        assert render("* text") == "* text"

    def test_right_flanking_requires_no_whitespace_before(self):
        # Right-flanking: before is not whitespace
        assert render("text *") == "text *"


class TestDelimiterMatching:
