        # Matching goes left to right, each closer matches nearest opener
        assert render("*a *b* c*") == "<em>a </em>b<em> c</em>"

    def test_matched_delimiters_removed_from_further_matching(self):
        # Delimiters between matched pair don't match
        assert render("**a *b* c**") == "<strong>a *b* c</strong>"


